from pathlib import Path
import base64,zlib,subprocess
ROOT=Path('.')
files=[
 'lib/features/meetings/meeting_room_page.dart',
 'lib/features/home/mobile_web_workspace.dart',
 'lib/features/home/home_shell.dart',
]
# Normalize text before applying the compact v1.2.5 patch so CI is independent of CRLF/LF.
for name in files:
 p=ROOT/name
 p.write_text(p.read_text())
patch=zlib.decompress(base64.b64decode(''))
r=subprocess.run(['patch','-p1','--forward','--batch'],input=patch,cwd=ROOT,capture_output=True)
if r.returncode:
 print(r.stdout.decode(errors='replace'))
 print(r.stderr.decode(errors='replace'))
 raise SystemExit(r.returncode)
nav="(()=>{\n  'use strict';\n  if(!window.EduNative)return;\n  const previous=window.EduMobileBack;\n  window.EduMobileBack=()=>{\n    // Preserve the established inner-chat flow first: keyboard -> chat list.\n    if(typeof previous==='function' && previous())return true;\n    let current='';\n    try{current=typeof S!=='undefined'?(S.page||''):'';}catch{}\n    if(current==='saved'){\n      if(typeof window.navigate==='function')window.navigate('chats');\n      return true;\n    }\n    if(['profile','notifications','meetings','chats','groups','people','admin'].includes(current)){\n      if(typeof window.navigate==='function')window.navigate('forum');\n      return true;\n    }\n    // Home/forum deliberately returns false so Flutter exits the app.\n    if(current==='forum')return false;\n    const root=document.querySelector('#page');\n    const heading=root?.querySelector('.ws-page-heading h1')?.textContent?.trim().toLowerCase()||'';\n    if(heading==='saved'){\n      if(typeof window.navigate==='function')window.navigate('chats');\n      return true;\n    }\n    if(/profile|notification|alert|call|meeting|chat|group/.test(heading)){\n      if(typeof window.navigate==='function')window.navigate('forum');\n      return true;\n    }\n    return false;\n  };\n})();\n"
p=ROOT/'assets/webapp/native-mobile-patch.js'
s=p.read_text()
if 'v1.2.5 Android navigation contract' not in s:
 p.write_text(s+'\n'+nav+'\n')
# Realtime profile changes refresh chat avatars/names; persistent EduPhotos CacheStorage handles reuse.
for name in ['assets/webapp/index.html','assets/webapp/app-web118.js','assets/webapp/app.js','assets/webapp/educhat-r4.js']:
 p=ROOT/name
 if not p.exists(): continue
 s=p.read_text()
 s=s.replace("'group_members','groups']","'group_members','groups','profiles']")
 p.write_text(s)
p=ROOT/'pubspec.yaml'
s=p.read_text()
import re
s=re.sub(r'^version:.*$', 'version: 1.2.5+24', s, flags=re.M)
p.write_text(s)
print('Applied EduChatPro v1.2.5 patch')
